import random

GROUP = "number_theory"
SKILL = "extremal_principle"

def count_ways(target, min_digit, max_digit):
    ways = [0] * (target + 1)
    ways[0] = 1

    for digit in range(min_digit, max_digit + 1):
        for i in range(target, digit - 1, -1):
            ways[i] += ways[i - digit]

    return ways[target]

def generate(seed):
    rng = random.Random(seed)

    min_digit = rng.randint(1, 5)
    max_digit = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)
    check_max_count = 0
    for digit in range(min_digit, max_digit + 1):
        if digit <= target_sum:
            check_max_count += count_ways(target_sum - digit, min_digit, digit - 1)

    answer = count_ways(target_sum, min_digit, max_digit)

    # Modify the problem to require finding the threshold number of digits needed to reach the target sum.
    threshold_count = 0
    for i in range(min_digit, max_digit + 1):
        if count_ways(target_sum, min_digit, i) > 0:
            threshold_count = i
            break

    # Ensure the threshold_count is such that it's the smallest number of digits that can produce at least one valid combination.
    check_threshold_count = 0
    for i in range(min_digit, max_digit + 1):
        if count_ways(target_sum, min_digit, i) > 0:
            check_threshold_count = i
            break

    assert answer == check_max_count, f"answer={answer} check={check_max_count}"
    assert threshold_count == check_threshold_count, f"threshold_count={threshold_count} check_threshold_count={check_threshold_count}"

    problem = (
        f"Determine the smallest number of digits {min_digit} to {threshold_count} (inclusive) that must be used "
        f"to ensure a set of digits can be formed such that their maximum digit does not exceed the target sum {target_sum} "
        f"and all digits sum to exactly {target_sum}. State only the integer."
    )
    return problem, str(answer)

