import random

GROUP = "combinatorics"
SKILL = "extremal_principle"

def count_ways(target, min_day, max_day):
    ways = [0] * (target + 1)
    ways[0] = 1

    for day in range(min_day, max_day + 1):
        if day > target:
            continue
        for i in range(target, day - 1, -1):
            ways[i] += ways[i - day]

    return ways[target]

def generate(seed):
    rng = random.Random(seed)

    min_day = rng.randint(1, 5)
    max_day = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)

    # Find the maximum number of days that can sum to target_sum without exceeding max_day.
    max_days = 0
    for day in range(min_day, max_day + 1):
        if count_ways(target_sum, min_day, day) > 0:
            max_days = day

    answer = count_ways(target_sum, min_day, max_days)
    assert answer == count_ways(target_sum, min_day, max_days), f"answer={answer} check={count_ways(target_sum, min_day, max_days)}"

    problem = (
        f"In a month where days can range from {min_day} to {max_day} (inclusive), "
        f"what is the maximum number of days that can sum to exactly {target_sum} without exceeding {max_days}? State only the integer."
    )
    return problem, str(answer)

import random
import itertools

GROUP = "algebra"
SKILL = "counting"

def count_polynomials(target, min_coeff, max_coeff):
    terms = set()
    for coeff in range(min_coeff, max_coeff + 1):
        if coeff > target:
            continue
        for comb in itertools.combinations_with_replacement(range(min_coeff, coeff + 1), target // coeff):
            if sum(comb) == target:
                terms.add(comb)

    return len(terms)

def generate(seed):
    rng = random.Random(seed)

    min_coeff = rng.randint(1, 3)
    max_coeff = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)

    # Find the number of distinct polynomials that can sum to target_sum.
    answer = count_polynomials(target_sum, min_coeff, max_coeff)
    assert answer == count_polynomials(target_sum, min_coeff, max_coeff), f"answer={answer} check={count_polynomials(target_sum, min_coeff, max_coeff)}"

    problem = (
        f"In a polynomial where coefficients can range from {min_coeff} to {max_coeff} (inclusive), "
        f"how many distinct polynomials have terms that sum exactly to {target_sum}? State only the integer."
    )
    return problem, str(answer)

