def count_distinct_polynomials(target, min_coeff, max_coeff):
    counts = {i: 0 for i in range(min_coeff, max_coeff + 1)}
    for coeff in range(min_coeff, max_coeff + 1):
        if coeff > target:
            continue
        counts[coeff] += 1

    distinct_terms = set()
    for coeff in range(min_coeff, max_coeff + 1):
        if coeff > target:
            continue
        for count in range(1, counts[coeff] + 1):
            if coeff * count > target:
                break
            remaining = target - coeff * count
            if remaining == 0:
                distinct_terms.add((count,))
                break
            if remaining < min_coeff:
                continue
            for sub_count in range(1, counts[remaining] + 1):
                if remaining * sub_count + coeff * count == target:
                    distinct_terms.add((count, sub_count))

    return len(distinct_terms)

def generate(seed):
    rng = random.Random(seed)

    min_coeff = rng.randint(1, 3)
    max_coeff = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)

    # Find the number of distinct polynomials that can sum to target_sum.
    answer = count_distinct_polynomials(target_sum, min_coeff, max_coeff)
    assert answer == count_distinct_polynomials(target_sum, min_coeff, max_coeff), f"answer={answer} check={count_distinct_polynomials(target_sum, min_coeff, max_coeff)}"

    problem = (
        f"In a polynomial where coefficients can range from {min_coeff} to {max_coeff} (inclusive), "
        f"how many distinct combinations of coefficients (not necessarily identical) have terms that sum exactly to {target_sum}? State only the integer."
    )
    return problem, str(answer)
